const { createApp } = Vue;

createApp({
  data() {
    return {
      todos: [
        { id: 1, text: 'Learn Vue', done: false },
        { id: 2, text: 'Build a project', done: false }
      ],
      newTodo: '',
      nextId: 3
    };
