const { createApp } = Vue;

createApp({
  data() {
    return {
      todos: [
        { id: 1, text: 'Learn Vue', done: false },
        { id: 2, text: 'Build a project', done: true }
      ],
      newTodo: '',
      nextId: 3,
      filter: 'all'
    };
  },
  computed: {
    visibleTodos() {
      if (this.filter === 'active') return this.todos.filter(t => !t.done);
      if (this.filter === 'completed') return this.todos.filter(t => t.done);
      return this.todos;
    }
  },
  methods: {
    addTodo() {
      this.todos.push({ id: this.nextId++, text: this.newTodo, done: false });
      this.newTodo = '';
    },
    toggleTodo(id) {
      const t = this.todos.find(t => t.id === id);
      if (t) t.done = !t.done;
    },
    deleteTodo(id) {
      this.todos = this.todos.filter(t => t.id !== id);
    }
  },
  template: `
    <div>
      <h1>Todo App</h1>
      <div>
        <button @click="filter = 'all'">All</button>
        <button @click="filter = 'active'">Active</button>
        <button @click="filter = 'completed'">Completed</button>
      </div>
      <input v-model="newTodo" />
      <button @click="addTodo">Add</button>
      <ul>
        <li v-for="t in visibleTodos" :key="t.id"
          @click="toggleTodo(t.id)"
          :style="{ textDecoration: t.done ? 'line-through' : 'none', cursor: 'pointer' }">
          {{ t.text }}
          <button @click.stop="deleteTodo(t.id)" style="margin-left: 8px">✕</button>
        </li>
      </ul>
    </div>
  `
}).mount('#root');
